# Journey definitions for the communication-service swim-lane page. Every text has a plain and a technical wording.
P = {
 "ui":       {"key":"ui","plain":"Outage screens","plain_sub":"what the on-call person sees and clicks","tech":"frontend (React SPA)","tech_sub":"src/outages: form, feed, EventSource client; proxied /v1"},
 "api":      {"key":"api","plain":"The service","plain_sub":"takes a notice, keeps it, tells everyone","tech":"communication-service","tech_sub":"WebFlux adapters → use cases (publishing, feed)"},
 "db":       {"key":"db","plain":"The record book","plain_sub":"every notice and every change, in order","tech":"MongoDB","tech_sub":"communications, communication_events (seq, 24 h TTL)"},
 "consumer": {"key":"consumer","plain":"Dependent systems","plain_sub":"every screen and system that reads the feed","tech":"consumers","tech_sub":"GET /v1/feed and SSE /v1/feed/stream clients"},
 "clock":    {"key":"clock","plain":"The clock","plain_sub":"moves notices on at their start and end times","tech":"StatusSweepUseCase","tech_sub":"@Scheduled every 30 s (communication.sweep.interval-ms)"},
 "system":   {"key":"system","plain":"A publishing system","plain_sub":"another tool that announces its own outages","tech":"API client","tech_sub":"any HTTP client with X-Client-Id"},
 "pod":      {"key":"pod","plain":"The team's app","plain_sub":"the container the sidecar watches","tech":"app container","tech_sub":"any HTTP service; /actuator/health when it has one"},
 "sidecar":  {"key":"sidecar","plain":"Health sidecar","plain_sub":"a small helper in the same pod","tech":"health-sidecar (Go)","tech_sub":"shares the pod's network namespace; :9465 /status"},
 "health":   {"key":"health","plain":"Health desk","plain_sub":"the part of the service that watches health","tech":"health slice","tech_sub":"HealthObservationUseCase, HealthSweepUseCase, HealthRollup"},
 "app":      {"key":"app","plain":"The watched app","plain_sub":"an app the service probes itself","tech":"probed endpoint","tech_sub":"GET <url> every intervalSeconds, WebClientHealthProbeAdapter"},
 "operator": {"key":"operator","plain":"Service operator (Alex)","plain_sub":"runs the communication service","tech":"operator","tech_sub":"admin routes under /v1/admin, logs, probes"},
 "platform": {"key":"platform","plain":"The cluster","plain_sub":"OpenShift, where pods start and stop","tech":"OpenShift / kubelet","tech_sub":"Downward API env, SIGTERM on delete, restricted-v2 SCC"},
 "servicenow":{"key":"servicenow","plain":"ServiceNow","plain_sub":"where the incident ticket lives","tech":"ServiceNow instance","tech_sub":"deep link only; communication.servicenow.instance-url"},
 "team":     {"key":"team","plain":"Publisher team (Priya)","plain_sub":"owns an app, wants it watched","tech":"publisher team","tech_sub":"owns the app's manifests"},
}
def parts(*keys): return [P[k] for k in keys]

JOURNEYS = []

JOURNEYS.append({"id":"publish","title":"Publish an outage and watch it land",
 "plain":"Sam publishes an outage from the screen; every dependent system sees it within a second, and sees it leave when Sam resolves it.",
 "tech":"POST /v1/communications through the client-id filter, a Mongo write plus an event-log append, SSE fan-out of `created`, then `POST …/retire` and a `retired` frame. Proven by `e2e/tests/02-f90-publish-live-resolve.spec.ts` (F-90).",
 "parts":parts("ui","api","db","consumer"),
 "steps":[
  {"part":"ui","start":True,"plain":"Sam picks the tenant, fills in Title, Severity and Affected services and presses Publish","tech":"The form runs `validation.ts` (severity floor for OUTAGE, time order, length caps) and sends `POST /v1/communications` with `X-Client-Id`","send":{"to":"api"}},
  {"part":"api","plain":"Checks who is calling and that the notice makes sense","tech":"`ClientIdWebFilter` wants `X-Client-Id` (401 without it); an unknown or misspelled field and a broken rule (`Communication#validateInvariants`) are a 400 with `{error}` naming the field"},
  {"part":"api","plain":"Writes the notice down","tech":"`PublishingUseCase` saves the document and appends a `created` event with the next global `seq`","send":{"to":"db"}},
  {"part":"db","plain":"Keeps the notice and adds a line to the log, in order","tech":"`communications` insert; `communication_events` gets `seq` from the counter (unique per log)","send":{"to":"api","kind":"answer"}},
  {"part":"api","plain":"Answers Sam: published","tech":"201 Created, `Location`, the `Communication` body with `version: 0`","send":{"to":"ui","kind":"answer"}},
  {"part":"ui","plain":"Shows the confirmation and offers View in feed and Publish another","tech":"`onPublished` renders the confirmation card; `onViewFeed(communication)` switches tab and filter and moves focus to the results"},
  {"part":"api","plain":"Tells everyone who is listening","tech":"the event-log tailer (polls every 500 ms) fans the `created` frame out to every open stream of that tenant","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"The outage appears on every screen within a second","tech":"SSE `id: <seq>`, `event: created`; the UI's `inFeed()` applies the same visibility rule as `GET /v1/feed`"},
  {"part":"ui","start":True,"plain":"Later Sam opens the feed, presses Resolve and confirms (\"Resolve as web-oncall? It leaves tenant acme's feed at once and cannot be reopened.\"); Escape would cancel","tech":"`POST /v1/communications/{id}/retire` with `{actor, note}`; Escape in the confirmation cancels and returns focus to Resolve","send":{"to":"api"}},
  {"part":"api","plain":"Marks the notice resolved and notes who did it","tech":"status RETIRED, history entry by `web-oncall`: `ACTIVE -> RETIRED: <note>`; a `retired` event is appended","send":{"to":"db"}},
  {"part":"db","plain":"Records the change","tech":"document `version: 1`, event `retired`","send":{"to":"api","kind":"answer"}},
  {"part":"api","plain":"Confirms to Sam and tells everyone","tech":"200 with the retired body; the tailer fans out `retired`","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"The card leaves every screen; a reload of the feed no longer lists it","tech":"`retired` frame removes the item; `GET /v1/feed` omits RETIRED; the permalink `GET /v1/communications/{id}` still shows it"},
 ]})

JOURNEYS.append({"id":"maintenance","title":"Schedule a maintenance window",
 "plain":"Sam announces Saturday's maintenance two days ahead. Consumers see it as upcoming, the clock turns it active on time and closes it when the window ends; until it starts Sam can withdraw it.",
 "tech":"A MAINTENANCE notice with `startsAt`/`endsAt` is stored SCHEDULED, listed by the feed inside the 7-day upcoming window, and moved SCHEDULED → ACTIVE → EXPIRED by `StatusSweepUseCase` with `activated`/`expired` frames.",
 "parts":parts("ui","api","db","clock","consumer"),
 "steps":[
  {"part":"ui","start":True,"plain":"Sam chooses Maintenance, sets Starts and Ends two days out and presses Publish","tech":"type MAINTENANCE needs `endsAt`; `startsAt` in the future → the service stores it SCHEDULED","send":{"to":"api"}},
  {"part":"api","plain":"Keeps it as scheduled, not live yet","tech":"status SCHEDULED, `created` event; indexes `sweep_*` make the clock's queries cheap","send":{"to":"db"}},
  {"part":"db","plain":"Records it","tech":"document + event","send":{"to":"api","kind":"answer"}},
  {"part":"api","plain":"Answers Sam and tells the listeners there is something upcoming","tech":"201; `created` frame carries status SCHEDULED","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"The window shows as Scheduled with a countdown; screens flip it to active on their own at the start time","tech":"`GET /v1/feed` includes SCHEDULED items starting within `communication.feed.upcoming-window` (7 days); the UI sets a timer at `startsAt`"},
  {"part":"ui","start":True,"plain":"Before it starts Sam could press Withdraw (\"Withdrawing retires it before it starts: tenant acme's consumers never see it and it cannot be reopened.\") — this time Sam lets it run","tech":"Withdraw is the same `POST …/retire`; a SCHEDULED notice retired never becomes active"},
  {"part":"clock","start":True,"plain":"Saturday 02:00: the clock finds the window has started","tech":"`StatusSweepUseCase` (every 30 s) selects SCHEDULED with `startsAt <= now`","send":{"to":"db"}},
  {"part":"db","plain":"The notice is now active; the change is on the log","tech":"status ACTIVE, history entry by `sweeper`: `SCHEDULED -> ACTIVE`, event `activated`","send":{"to":"api","kind":"answer"}},
  {"part":"api","plain":"Tells everyone the maintenance is on","tech":"`activated` frame","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"The card turns active everywhere","tech":"frame applied; a client that missed it gets the same state on `GET /v1/feed`"},
  {"part":"clock","start":True,"plain":"At the end time the clock closes it","tech":"ACTIVE with `endsAt`/`expiresAt <= now` → EXPIRED, history entry by `sweeper`: `ACTIVE -> EXPIRED`, event `expired`","send":{"to":"db"}},
  {"part":"db","plain":"Marked finished","tech":"status EXPIRED; retire afterwards answers 409 \"already expired; retiring would rewrite history\"","send":{"to":"api","kind":"answer"}},
  {"part":"api","plain":"Tells everyone it is over","tech":"`expired` frame","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"The card leaves; the record stays readable by its link","tech":"feed omits EXPIRED; permalink and history keep it"},
 ]})

JOURNEYS.append({"id":"api-publish","title":"A system publishes through the API, safely twice",
 "plain":"A deployment tool announces an incident with its own reference. A retry does not create a second notice; a follow-up for the same incident needs a new reference; an update says which version it is editing.",
 "tech":"`externalRef` is a permanent idempotency key per tenant (unique index): same body → the same notice, a second notice → 409 naming the holder, with the first follow-up value still free in `suggestedExternalRef`; `PUT` carries `expectedVersion` and gets 409 on a stale version (optimistic `@Version`); misspelled fields are one 400 that names every one of them (`unknown fields 'sevrity', 'tittle'; known fields: …`).",
 "parts":parts("system","api","db","consumer"),
 "steps":[
  {"part":"system","start":True,"plain":"The tool posts an incident with reference INC-1 and its own name in the caller header","tech":"`POST /v1/communications` with `externalRef: \"INC-1\"`, `X-Client-Id: deploy-tool`","send":{"to":"api"}},
  {"part":"api","plain":"Stores it under that reference","tech":"insert; unique index `external_ref_idx` on `(tenantId, externalRef)`","send":{"to":"db"}},
  {"part":"db","plain":"One notice, one reference","tech":"document `version: 0`","send":{"to":"api","kind":"answer"}},
  {"part":"api","plain":"Answers: created","tech":"201 + body","send":{"to":"system","kind":"answer"}},
  {"part":"system","plain":"The network blipped, so the tool sends exactly the same request again","tech":"identical body, same `externalRef`","send":{"to":"api"}},
  {"part":"api","plain":"Recognises the reference and gives back the same notice instead of a duplicate","tech":"lookup by `(tenantId, externalRef)`; the retry is answered with the existing notice, nothing is written"},
  {"part":"api","plain":"Answers with the same notice","tech":"same id, same `version`","send":{"to":"system","kind":"answer"}},
  {"part":"system","plain":"A week later the incident reopens; the tool tries INC-1 again with a new title","tech":"different body, same `externalRef`","send":{"to":"api"}},
  {"part":"api","plain":"Refuses and explains: the reference is taken for good; INC-1-2 is still free","tech":"409 `{\"error\": \"externalRef 'INC-1' is already used by notice <id> in tenant acme. externalRef is a permanent idempotency key: … (for example INC-1-2, which is still free).\", \"suggestedExternalRef\": \"INC-1-2\"}`; past 50 taken follow-ups it says so and suggests none (documented in `/v3/api-docs`)","send":{"to":"system","kind":"answer"}},
  {"part":"system","plain":"The tool publishes the follow-up under INC-1-2, then edits the first notice's text","tech":"`POST` with `externalRef: \"INC-1-2\"` → 201; then `PUT /v1/communications/{id}` with `expectedVersion: 0`","send":{"to":"api"}},
  {"part":"api","plain":"Edits only if nobody changed it meanwhile","tech":"`@Version` check: 409 \"expectedVersion 0 does not match current version 1\" when stale; 400 \"expectedVersion is required: …\" when missing","send":{"to":"db"}},
  {"part":"db","plain":"The edit and its history line","tech":"`version` +1, `updated` event","send":{"to":"api","kind":"answer"}},
  {"part":"api","plain":"Tells everyone about the new notice and the edit","tech":"`created` and `updated` frames","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"Both notices are on every screen, the first with its new wording","tech":"clients apply frames by `(id, version)`, so a repeated frame is harmless"},
 ]})

JOURNEYS.append({"id":"consume","title":"A dependent system reads the feed and stays current",
 "plain":"Team B's app loads what is live for its tenant once, then keeps a line open for changes. When the line drops it picks up exactly where it left off.",
 "tech":"`GET /v1/feed` for the first page, then SSE `GET /v1/feed/stream?tenantId=` with `X-Client-Id` (or `?clientId=`), `: connected` at once, keepalive every 15 s, `Last-Event-ID` or `?lastEventId=` (with both, the larger wins) replays from the event log, a `snapshot` frame when the id is too old (log keeps 24 h).",
 "parts":parts("consumer","api","db"),
 "steps":[
  {"part":"consumer","start":True,"plain":"Team B's app asks for everything live for its tenant, narrowed to its services","tech":"`GET /v1/feed?tenantId=acme&service=payments-api` with `X-Client-Id: team-b-app`","send":{"to":"api"}},
  {"part":"api","plain":"Reads the current list","tech":"`FeedUseCase` query on `feed_idx`; a first page of 20 (`?page=&size=`), `hasNext` when there is more","send":{"to":"db"}},
  {"part":"db","plain":"The live and upcoming notices","tech":"ACTIVE now plus SCHEDULED within 7 days","send":{"to":"api","kind":"answer"}},
  {"part":"api","plain":"Answers with the list","tech":"`Page<FeedItem>`","send":{"to":"consumer","kind":"answer"}},
  {"part":"consumer","plain":"Shows them and opens the live line","tech":"`GET /v1/feed/stream?tenantId=acme` (SSE)","send":{"to":"api"}},
  {"part":"api","plain":"Opens the line at once and sends the current picture first","tech":"`: connected` comment immediately; one `snapshot` frame per visible notice, stamped with the log head, then live frames","send":{"to":"consumer","kind":"answer"}},
  {"part":"consumer","plain":"From now on every change arrives as it happens; a quiet line still ticks every 15 s","tech":"`created|updated|retired|activated|expired` frames with `id: <seq>`; `:keepalive` every 15 s"},
  {"part":"consumer","start":True,"plain":"The line drops (proxy restart). The app reopens it saying the last number it saw","tech":"browser/EventSource retries with `Last-Event-ID: 41`; non-browser clients send `?lastEventId=41`","send":{"to":"api"}},
  {"part":"api","plain":"Replays what was missed since that number, then continues live","tech":"`findTenantEventsInWindow(tenant, 41, head)` on `events_tenant_seq_idx`; frames 42… then live; an id older than the log → `snapshot` instead","send":{"to":"db"}},
  {"part":"db","plain":"The missed lines of the log","tech":"`communication_events` (TTL 24 h)","send":{"to":"api","kind":"answer"}},
  {"part":"api","plain":"Sends the missed changes","tech":"at-least-once: a frame can repeat, never be skipped (snapshot id = log head read before the snapshot)","send":{"to":"consumer","kind":"answer"}},
  {"part":"consumer","plain":"Nothing was lost; the app did not have to reload the whole list","tech":"dedupe on `(id, version)`"},
 ]})

JOURNEYS.append({"id":"sidecar-outage","title":"The sidecar notices the team's app is down",
 "plain":"Priya's app starts with the sidecar beside it. When the app's database fails, the sidecar sees it within seconds, the service opens an outage with the detail, and closes it when the app recovers. Nobody on Priya's team touched a keyboard.",
 "tech":"Discovery via /proc/net/tcp, `GET /actuator/health` every 15 s (retry after 2 s), UNKNOWN until the app first answers UP (grace 5 min), `POST /v1/health/reports` on a change, after every probe while DOWN or DEGRADED, and at the 30 s heartbeat; per-pod `health_instances`, `HealthRollup`, debounce `failureThreshold` 2 → OUTAGE, `recoveryThreshold` 2 → retired. Proven by `e2e/tests/03-f91-sidecar-auto-notice.spec.ts` (F-91).",
 "parts":parts("platform","pod","sidecar","health","consumer"),
 "steps":[
  {"part":"platform","start":True,"plain":"The cluster starts Priya's pod: her app and the health sidecar together","tech":"Pod with the sidecar container (or native init container, `restartPolicy: Always`); Downward API sets `POD_NAME`, `POD_NAMESPACE`, `NODE_NAME`","send":{"to":"sidecar"}},
  {"part":"sidecar","plain":"Looks for the app inside the pod and finds its health page","tech":"lists listening ports from `/proc/net/tcp`, tries `/actuator/health` lowest port first, keeps the first target that answers","send":{"to":"pod"}},
  {"part":"pod","plain":"Still starting: not healthy yet","tech":"`503 {\"status\":\"DOWN\"}` or connection refused during boot","send":{"to":"sidecar","kind":"answer"}},
  {"part":"sidecar","plain":"Says \"don't know yet\" rather than \"down\" while the app boots (up to 5 minutes)","tech":"UNKNOWN (\"starting: waiting for the first healthy answer from …\") during `CS_STARTUP_GRACE`, sent on a change and at the heartbeat; the service does not count UNKNOWN pods, so rolling deploys never open notices","send":{"to":"health"}},
  {"part":"health","plain":"Registers the app automatically the first time it hears from it","tech":"`POST /v1/health/reports` 202; push-only monitor `(tenant, service)` auto-registered with the report's publisher; `health_instances` row for the pod"},
  {"part":"pod","start":True,"plain":"The app is up","tech":"`200 {\"status\":\"UP\",\"components\":{\"db\":{\"status\":\"UP\"}}}`","send":{"to":"sidecar","kind":"answer"}},
  {"part":"sidecar","plain":"Reports UP; from now on it only speaks when something changes or every 30 s","tech":"`upSeen: true`; send policy change-or-heartbeat (`CS_HEARTBEAT` 30 s)","send":{"to":"health"}},
  {"part":"health","plain":"Rolls the pods of the service up: healthy","tech":"`HealthRollup` over live pods: all UP → UP; some UP → UP while ≥ `minHealthyPercent` (50 %) are UP and none is DEGRADED; none UP → DOWN; stored in `health_monitors` and `health_instances` (24 h TTL)"},
  {"part":"pod","start":True,"plain":"The app's database fails: the app says it is down because of db","tech":"`503 {\"status\":\"DOWN\",\"components\":{\"db\":{\"status\":\"DOWN\"}}}` (`show-details: always`)","send":{"to":"sidecar","kind":"answer"}},
  {"part":"sidecar","plain":"Checks again two seconds later so a hiccup does not count, then reports DOWN with the detail, and keeps reporting after every probe while it stays down","tech":"retry after `CS_RETRY_DELAY` 2 s; DOWN report with `components.db`; while not UP a report follows every probe (15 s)","send":{"to":"health"}},
  {"part":"health","plain":"Waits for a second DOWN before acting, then opens an outage: \"fake-app is down\" with the failing part named, written down like any other notice","tech":"`failureThreshold` 2 consecutive DOWN rollups → `PublishingUseCase` creates an OUTAGE titled \"fake-app is down\" (severity MAJOR, publisher `health-sidecar` from the monitor's policy, plain-text body: status as of the UTC second, \"Reported by its pods: 0 of 1 pod UP (DOWN: <pod>)\", \"Failing components: db: DOWN\"); `created` event; the monitor keeps `openCommunicationId`","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"Team B sees \"fake-app is down\" about 30 s after the database failed, with the reason","tech":"card shows publisher health-sidecar, the pod name and `db: DOWN`; DEGRADED would have opened a HEALTH notice (MINOR) instead"},
  {"part":"pod","start":True,"plain":"The database is back; the app is healthy again","tech":"`200 UP`","send":{"to":"sidecar","kind":"answer"}},
  {"part":"sidecar","plain":"Reports UP","tech":"transition logged at INFO; back to change-or-heartbeat","send":{"to":"health"}},
  {"part":"health","plain":"After a second healthy report it closes the outage by itself","tech":"`recoveryThreshold` 2 → retire with actor `health-sidecar` and note `recovered: UP (1 of 1 pod UP)`, `retired` event","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"The outage leaves every screen","tech":"`retired` frame; history shows the whole episode"},
 ]})

JOURNEYS.append({"id":"sidecar-crash","title":"The app crashes, or the pod disappears",
 "plain":"Three ways a pod can stop answering, and what each one looks like: the app process dies, the cluster deletes the pod cleanly, or the pod vanishes without a word.",
 "tech":"Port vanished → DOWN \"app is not listening (last target …)\" from the first failed probe; SIGTERM → final report with `instance.leaving: true` (pod leaves the rollup at once); no reports for `staleAfterSeconds` (90 s) → the sweep marks the pod stale, DOWN when no live pod is left.",
 "parts":parts("platform","pod","sidecar","health","consumer"),
 "steps":[
  {"part":"pod","start":True,"plain":"The app process crashes; nothing listens on its port any more","tech":"port gone from `/proc/net/tcp`; the pinned/discovered target refuses connections","send":{"to":"sidecar","kind":"answer"}},
  {"part":"sidecar","plain":"Reports DOWN at once: \"app is not listening\", and says so after every probe until it is back","tech":"`notListening()` on the probe that finds the port gone; rediscovery runs while it is DOWN; `/status.lastTarget` keeps the old target","send":{"to":"health"}},
  {"part":"health","plain":"Second DOWN → outage opened; when the app comes back and answers UP twice → closed","tech":"same debounce as any DOWN; crash-looping containers therefore show as one outage, not a flap","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"\"fake-app is down: app is not listening\" on every screen","tech":"OUTAGE card, publisher health-sidecar"},
  {"part":"platform","start":True,"plain":"A deploy or a scale-down deletes the pod cleanly","tech":"kubelet sends SIGTERM to every container, sidecar included","send":{"to":"sidecar"}},
  {"part":"sidecar","plain":"Sends one last message: \"this pod is leaving\"","tech":"final `POST /v1/health/reports` with `instance.leaving: true`, then exit 0 (`leaving report sent`)","send":{"to":"health"}},
  {"part":"health","plain":"Takes the pod out of the count straight away, so a scale-down never looks like an outage","tech":"instance marked `left`; rollup over the remaining live pods; scale-to-zero leaves nothing stale","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"Nothing changes for consumers unless the last pod left while down","tech":"no frame unless the rollup status changed"},
  {"part":"platform","start":True,"plain":"A node dies: the pod vanishes with no goodbye","tech":"no SIGTERM delivered; the sidecar's last report ages","send":{"to":"health"}},
  {"part":"health","plain":"After 90 s of silence the desk treats the pod as gone; if no healthy pod is left, the service is down","tech":"`HealthSweepUseCase` every 5 s: a pod not heard from for 90 s (`instance-stale-after-seconds`) is no longer live; when the whole service has been silent that long the sweep observes DOWN \"1 pod has not reported since <UTC> (<pod>)\"; safety valve: paused while more than 30 % of the monitors (and at least 2) are silent together, and for 5 minutes after the service itself starts","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"The outage opens about a minute and a half after the pod last reported; it closes once a new pod reports healthy","tech":"stale at 90 s, two sweeps 5 s apart reach `failureThreshold` 2 → OUTAGE; retired after `recoveryThreshold` UP reports from the new pod"},
 ]})

JOURNEYS.append({"id":"rollout","title":"Several pods and a rolling deploy",
 "plain":"Priya's app runs three pods. One pod can be unhealthy without a notice; a rolling deploy never opens one; two unhealthy pods out of three open a health notice, and an outage follows only when no pod is left healthy.",
 "tech":"Per-pod records in `health_instances`; `HealthRollup` over live pods: all UP → UP; some UP → UP while ≥ `minHealthyPercent` (50 %) are UP and none is DEGRADED (UP with a failing component), otherwise DEGRADED; none UP → DOWN; UNKNOWN (starting) pods are live but not tallied; `leaving` pods are out at once. Native sidecars start before and stop after the app.",
 "parts":parts("platform","sidecar","health","consumer"),
 "steps":[
  {"part":"platform","start":True,"plain":"Three pods run, each with its sidecar","tech":"3 × (app + health-sidecar); `CS_SERVICE` from `app.kubernetes.io/name`, so all three feed one monitor","send":{"to":"sidecar"}},
  {"part":"sidecar","plain":"Each sidecar reports its own pod","tech":"`instance.id` = pod name; 3 rows under the same `(tenant, service)` monitor","send":{"to":"health"}},
  {"part":"health","plain":"Counts pods, not messages: 3 of 3 healthy","tech":"rollup UP, message `3 of 3 pods UP`; `GET /v1/health/monitors/{id}/instances` lists them"},
  {"part":"platform","start":True,"plain":"A rolling deploy replaces the pods one at a time","tech":"new pod: sidecar UNKNOWN during grace; old pod: SIGTERM → `leaving`","send":{"to":"sidecar"}},
  {"part":"sidecar","plain":"New pods say \"starting\", old pods say \"leaving\"","tech":"UNKNOWN reports (not tallied) and `leaving: true` reports (removed at once)","send":{"to":"health"}},
  {"part":"health","plain":"Never below the healthy share during the deploy: no notice","tech":"live pods 2–3, UP share stays ≥ 50 %; no DOWN rollup, no debounce started"},
  {"part":"sidecar","start":True,"plain":"Later one pod's app hangs","tech":"one pod DOWN, two UP","send":{"to":"health"}},
  {"part":"health","plain":"One of three unhealthy is still a healthy service: nothing is published, because the cluster already keeps callers away from the bad pod","tech":"rollup UP, `2 of 3 pods UP (DOWN: <pod>)`: 66 % ≥ 50 %; a pod answering UP with a failing component would make the rollup DEGRADED"},
  {"part":"sidecar","start":True,"plain":"A second pod fails too","tech":"two of three DOWN","send":{"to":"health"}},
  {"part":"health","plain":"Below half healthy, twice in a row: a health notice opens (degraded, not down), naming the pods","tech":"rollup DEGRADED, `1 of 3 pods UP (DOWN: <pod>, <pod>)`: 33 % < 50 % → `failureThreshold` 2 → HEALTH notice, severity MINOR","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"\"fake-app is degraded\" with the pod names in the detail; if the last pod fails too, an outage takes its place","tech":"body \"Reported by its pods: 1 of 3 pods UP (DOWN: …)\"; all three DOWN → rollup DOWN → the HEALTH notice is retired (\"reclassified as DOWN\") and an OUTAGE (MAJOR) opens"},
 ]})

JOURNEYS.append({"id":"pull-monitor","title":"The service probes an app itself",
 "plain":"For an app that cannot run a sidecar, Alex registers its health page. The service checks it every 30 seconds, opens a notice when it degrades, replaces it with an outage when it is down, and closes it when it recovers.",
 "tech":"`POST /v1/health/monitors` with a `url` creates a pull monitor (interval 30 s, timeout 5 s); `HealthSweepUseCase` probes due monitors through `WebClientHealthProbeAdapter`; the health document wins over the HTTP status; DEGRADED → HEALTH notice (MINOR); DOWN → OUTAGE (MAJOR), which replaces an open HEALTH notice; a change of failing components updates the open notice in place; retired after `recoveryThreshold` UP. Proven by `e2e/tests/06-f39-pull-monitor.spec.ts`.",
 "parts":parts("operator","health","app","consumer"),
 "steps":[
  {"part":"operator","start":True,"plain":"Alex registers the app's health page for tenant acme","tech":"`POST /v1/health/monitors {tenantId, service, url: \"https://legacy/health\"}` → 201 + `Location`; 409 if the pair exists; 400 for a bad url or a misspelled policy field (`intervalSecond`), which it names with the known ones","send":{"to":"health"}},
  {"part":"health","plain":"Checks the page right away, then every 30 seconds","tech":"`POST …/{id}/probe` on demand (when it races the scheduler it applies the observation it made instead of probing again); the sweep probes a monitor once its interval has passed since `lastProbeAt`, claiming the slot first so two instances never probe it twice","send":{"to":"app"}},
  {"part":"app","plain":"Healthy","tech":"`200 {\"status\":\"UP\"}`","send":{"to":"health","kind":"answer"}},
  {"part":"health","plain":"Notes the result","tech":"`lastStatus UP (HTTP 200)`, `lastProbeAt`, streaks reset; `health_monitors` row with optimistic `@Version`"},
  {"part":"app","start":True,"plain":"The app's cache is down: it answers \"degraded\"","tech":"`200 {\"status\":\"DEGRADED\",\"components\":{\"cache\":{\"status\":\"DOWN\"}}}`: the document wins over the 200","send":{"to":"health","kind":"answer"}},
  {"part":"health","plain":"Second degraded probe in a row: opens a health notice, not an outage","tech":"HEALTH notice, severity MINOR, body names `cache`","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"\"legacy is degraded\" appears","tech":"HEALTH card"},
  {"part":"app","start":True,"plain":"Now the page does not answer at all","tech":"connection refused / no response within 5000 ms → `DOWN (probe failed: …)`","send":{"to":"health","kind":"answer"}},
  {"part":"health","plain":"Second failure: the health notice is closed and an outage takes its place","tech":"REPLACE: the HEALTH notice is retired with note `reclassified as DOWN: …`, a new OUTAGE (MAJOR) is created","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"The health card leaves and an outage card appears","tech":"`retired` frame for the HEALTH notice, `created` frame for the OUTAGE"},
  {"part":"app","start":True,"plain":"Fixed: healthy again","tech":"`200 UP` twice","send":{"to":"health","kind":"answer"}},
  {"part":"health","plain":"Closes the notice","tech":"`recoveryThreshold` 2 → retired by the monitor's publisher (`health-monitor` unless set at registration) with note `recovered: UP (HTTP 200)`","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"Gone from the feed; the history tells the story","tech":"`retired` frame"},
 ]})

JOURNEYS.append({"id":"operator-retire","title":"Alex resolves an automatic outage by hand",
 "plain":"An automatic outage is open but the team confirmed the app is fine for customers. Alex resolves it. The service respects that, keeps watching, and only reopens if the app keeps failing.",
 "tech":"`POST /v1/communications/{id}/retire` on a notice owned by a monitor: `HealthMonitor.withClosedByOperator()` clears `openCommunicationId`, the observation that notices the retire counts as the first of a new streak, so a reopen takes exactly `failureThreshold` failing observations.",
 "parts":parts("operator","api","health","consumer"),
 "steps":[
  {"part":"operator","start":True,"plain":"Alex resolves the automatic outage with a note","tech":"`POST /v1/communications/{id}/retire {actor: \"alex\", note: \"false alarm, read replica only\"}`","send":{"to":"api"}},
  {"part":"api","plain":"Retires it like any notice and tells everyone","tech":"status RETIRED, history `alex: ACTIVE -> RETIRED (note)`, `retired` frame","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"The outage leaves the screens","tech":"`retired` frame"},
  {"part":"health","start":True,"plain":"At the next check the desk sees its notice was closed by a person and starts counting afresh","tech":"`withClosedByOperator()`: `openCommunicationId` cleared; this failing observation = streak 1"},
  {"part":"health","plain":"If the app is still failing at the following check, a new outage opens (threshold 2)","tech":"streak reaches `failureThreshold` → new notice, new id; the old one stays RETIRED"},
  {"part":"health","plain":"If instead it recovers, nothing more happens","tech":"UP observations reset the streak; no notice to retire"},
  {"part":"api","plain":"Either way the record shows who closed what and why","tech":"permalink + history of the old notice; the monitor at `GET /v1/health/monitors/{id}` shows streaks and `openCommunicationId`","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"A reopened outage arrives as a new card","tech":"`created` frame"},
 ]})

JOURNEYS.append({"id":"restart","title":"The service restarts while screens are open",
 "plain":"The service is redeployed during the day. Screens show \"Reconnecting\", keep what they had, catch up on anything published meanwhile and go back to \"Live\" without a reload.",
 "tech":"The proxy ends the SSE response; EventSource's own retry sends `Last-Event-ID`; when a retry is answered with anything but 200 the client reopens itself with backoff 1,2,4,8,10 s and `?lastEventId=<last seq>`, then reloads `/v1/feed` once (`reconcile()`). Proven by `e2e/tests/04-f92-backend-restart.spec.ts` (F-92).",
 "parts":parts("ui","api","db","system"),
 "steps":[
  {"part":"ui","start":True,"plain":"Sam has the feed open; the badge says Live","tech":"EventSource open on `/v1/feed/stream?tenantId=acme&clientId=communication-frontend`, last `id` seen = 57; *Live* is shown once a frame arrives, or after 6 s on a quiet stream (`STREAM_SETTLE_MS`)"},
  {"part":"api","start":True,"plain":"The service is stopped for a redeploy","tech":"`ContextClosedEvent` → `closeStreams()` completes every SSE response; readiness goes 503 first","send":{"to":"ui","kind":"answer"}},
  {"part":"ui","plain":"Badge: Reconnecting (1), (2)… the cards stay on screen","tech":"browser retry with `Last-Event-ID: 57` fails → client reopen with backoff 1 s, 2 s, 4 s, 8 s, 10 s cap; `lastSeq` kept across attempts"},
  {"part":"system","start":True,"plain":"Meanwhile another instance (or the restarted one) accepts a new outage from a tool","tech":"`POST /v1/communications` on the other instance; event `seq 58` appended","send":{"to":"db"}},
  {"part":"db","plain":"Line 58 on the log","tech":"`communication_events` is shared by every instance","send":{"to":"system","kind":"answer"}},
  {"part":"system","plain":"The tool got its confirmation","tech":"201 from whichever instance answered"},
  {"part":"api","start":True,"plain":"The service is back","tech":"readiness 200; the Mongo indexes are checked at start","send":{"to":"ui","kind":"answer"}},
  {"part":"ui","plain":"The next attempt opens, asking for everything after 57","tech":"`GET /v1/feed/stream?tenantId=acme&clientId=…&lastEventId=57`","send":{"to":"api"}},
  {"part":"api","plain":"Replays 58 and continues live","tech":"`findTenantEventsInWindow(acme, 57, head)` → `created` 58; then live tailing","send":{"to":"db"}},
  {"part":"db","plain":"The missed line","tech":"query on `events_tenant_seq_idx`","send":{"to":"api","kind":"answer"}},
  {"part":"api","plain":"Sends it","tech":"frame `id: 58`","send":{"to":"ui","kind":"answer"}},
  {"part":"ui","plain":"The new outage appears, the badge says Live again; a quiet reload of the list makes sure nothing slipped through","tech":"`reconcile()` → one `GET /v1/feed`; the attempt counter is reset once the reopened stream has worked (a frame, or 6 s without an error), not on `onopen` alone"},
 ]})

JOURNEYS.append({"id":"mongo-down","title":"The record book is unreachable",
 "plain":"The database behind the service fails. Callers get a clear \"database unavailable\" within seconds instead of hanging, screens say the service cannot reach its database, the health checks keep the pod out of traffic, and everything resumes by itself when the database is back.",
 "tech":"`MongoClientSettingsBuilderCustomizer`: server selection 5 s, connect 5 s, read 15 s (`communication.mongo.*`); driver failures → 503 `{\"error\":\"database unavailable\"}` in `GlobalExceptionHandler`; readiness pings Mongo with a 0.8 s timeout (`MongoReadinessIndicator`) and answers 503, liveness 200, with one WARN when the database stops answering and one INFO when it is back; a stream opened during the outage is a JSON 503 before any byte; sweeps log one WARN per run without stack trace and keep running. Proven by `e2e/tests/07-f92-database-down.spec.ts`. Known gap (GAP-backend4-1): a database that hangs, rather than refusing connections, can make the driver pause its pool, and those calls answer 500 with the driver's message, which names the database host.",
 "parts":parts("ui","api","db","clock","operator"),
 "steps":[
  {"part":"db","start":True,"plain":"The database stops answering","tech":"replica set unreachable; the driver's cluster state goes UNKNOWN","send":{"to":"api","kind":"answer"}},
  {"part":"api","plain":"Every request now fails fast with a plain explanation (no internal addresses in the answer)","tech":"`DataAccessResourceFailureException` / `MongoTimeoutException` / `MongoSocketException` → 503 `database unavailable` after 5 s when the database refuses connections; the driver text is in the log at WARN only. When the database hangs instead, the pool-paused error is not recognised yet and answers 500 with the driver text (GAP-backend4-1, open)"},
  {"part":"ui","start":True,"plain":"Sam tries to publish","tech":"`POST /v1/communications` as usual","send":{"to":"api"}},
  {"part":"api","plain":"Says so within seconds","tech":"503 `{\"error\":\"database unavailable\"}` after about 5 s instead of a 500 after 30 s; a stream opened now gets the same JSON 503 before any byte (G-4-10)","send":{"to":"ui","kind":"answer"}},
  {"part":"ui","plain":"Sam reads \"The service cannot reach its database right now (HTTP 503): database unavailable. It recovers on its own; try again in a moment.\" The cards already on screen stay; a feed opened now says Service degraded instead of Live","tech":"`explainError()` recognises the service's own 503 body (a refused connection or a proxy's 502/504 still reads \"unreachable\"); the banner takes focus; the feed's load error is a `role=alert`; a stream answered 503 shows the badge *Service degraded* and reopens with backoff; an already open stream stays up on keepalives"},
  {"part":"clock","start":True,"plain":"The clock keeps trying its rounds and notes each failure once, quietly","tech":"`StatusSweepUseCase` / `HealthSweepUseCase`: one WARN `status sweep skipped: database unavailable: …` / `health sweep skipped: …` per run, stack trace at DEBUG","send":{"to":"api"}},
  {"part":"api","plain":"Tells the cluster it is not ready, but alive","tech":"`/actuator/health/readiness` 503 within 0.8 s, inside a kubelet's default 1 s probe timeout (`communication.mongo.readiness-timeout`), `/liveness` 200: the pod leaves the Service endpoints, is not restarted","send":{"to":"operator","kind":"answer"}},
  {"part":"operator","plain":"Alex sees the readiness alarm and the single WARN line per sweep in the logs","tech":"one `WARN readiness DOWN: MongoDB did not answer a ping: …` per outage, one WARN per skipped sweep, one WARN when the event-log poller stops and one INFO when it works again, the driver's cluster logger at WARN: no ERROR storm; settings in the README section \"When Mongo is down\""},
  {"part":"db","start":True,"plain":"The database is back","tech":"server selection succeeds again","send":{"to":"api","kind":"answer"}},
  {"part":"api","plain":"Ready again within seconds; nothing to restart","tech":"`INFO readiness UP: MongoDB answers again` at the next probe, readiness 200; sweeps resume; streams reopened by clients replay from their last id","send":{"to":"ui","kind":"answer"}},
  {"part":"ui","plain":"Try again works; the live line reconnects by itself and the badge goes back to Live","tech":"`reconcile()` after reopen. Known gap (UX-65): a page whose list load failed while its stream kept working keeps the error until Try again"},
 ]})

JOURNEYS.append({"id":"valve","title":"Many sidecars fall silent at once",
 "plain":"A network change cuts every sidecar off from the service for a while. The service must not declare half the company down; it pauses the \"no news is bad news\" rule while the silence is widespread, and ignores monitors that were abandoned long ago.",
 "tech":"`HealthSweepUseCase` staleness valve: no stale-DOWN while more than `stale-pause-fraction` (0.3) of the monitors that can go stale, and at least `stale-pause-min-silent` (2), are silent together; monitors silent longer than `stale-forget-after` (PT24H) are outside both counts; scaled-to-zero services (all pods left) are never stale.",
 "parts":parts("sidecar","health","operator","consumer"),
 "steps":[
  {"part":"sidecar","start":True,"plain":"Forty sidecars can no longer reach the service; each keeps its latest status and retries with growing pauses","tech":"`sendError` set; retries after 1, 2, 4, 8, 16, then every 30 s, each less up to a fifth at random; only the latest report is kept; the apps are unaffected","send":{"to":"health"}},
  {"part":"health","plain":"After 90 s all forty are silent. Forty silent out of forty is not forty outages: the desk pauses the rule","tech":"silent share 100 % > 30 % and ≥ 2 → stale-DOWN paused; one WARN `40 of 40 push-only monitors are silent at once; not declaring them DOWN until some report again (can the clusters reach this service?)`"},
  {"part":"operator","start":True,"plain":"Alex sees the warning and knows the network is the problem, not the apps","tech":"log line with silent/total; monitors show `lastReportAt` ageing"},
  {"part":"sidecar","start":True,"plain":"The network is fixed; the sidecars catch up with their current status","tech":"next retry succeeds; one INFO `report delivered again` with `failedAttempts` and `failingFor`; `reportsSent` resumes","send":{"to":"health"}},
  {"part":"health","plain":"Fresh reports lift the pause; a pod that really died meanwhile is handled normally","tech":"silent share drops below 30 %; INFO `staleness evaluation resumed`; staleness is judged per monitor again","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"Only the genuinely dead service gets an outage","tech":"one OUTAGE, not forty"},
  {"part":"health","start":True,"plain":"Months-old test monitors nobody decommissioned no longer count","tech":"silent longer than `stale-forget-after` (24 h) → excluded from numerator and denominator; nothing deleted; counted again if they report"},
  {"part":"operator","plain":"Alex can delete them for good when convenient","tech":"`DELETE /v1/health/monitors/{id}`"},
 ]})

JOURNEYS.append({"id":"ticket","title":"Tie a notice to its ServiceNow incident",
 "plain":"Sam adds the incident number when publishing. The notice carries it, consumers see a chip that opens the ticket, and the number doubles as the notice's reference so a retry never duplicates it.",
 "tech":"`ticket {system, number, url}` on the command; `TicketPolicy` trims and upper-cases, checks `INC\\d{7}`, defaults system to servicenow and builds `{instance}/nav_to.do?uri=incident.do%3Fsysparm_query%3Dnumber%3DINC…` when `communication.servicenow.instance-url` is set; `externalRef` defaults to the number. Tickets are optional on every notice type.",
 "parts":parts("ui","api","db","consumer","servicenow"),
 "steps":[
  {"part":"ui","start":True,"plain":"Sam fills in the outage and types the incident number INC0012345","tech":"`ticket.number` from the optional ServiceNow incident field; hint says the chip is linked when the service knows the instance","send":{"to":"api"}},
  {"part":"api","plain":"Tidies the number, checks its shape and, when it knows the ServiceNow address, attaches a link","tech":"`TicketPolicy`: trim, upper-case (`Locale.ROOT`), pattern `communication.tickets.number-pattern`; url only with `communication.servicenow.instance-url`","send":{"to":"db"}},
  {"part":"db","plain":"The notice with its ticket; the number is also its reference","tech":"`ticket {system: servicenow, number, url}`, `externalRef: INC0012345` (unique per tenant)","send":{"to":"api","kind":"answer"}},
  {"part":"api","plain":"Answers Sam and tells everyone","tech":"201; `created` frame carries the ticket","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"The card shows an INC0012345 chip","tech":"`TicketTag` on the card and the confirmation"},
  {"part":"consumer","start":True,"plain":"Team B clicks the chip","tech":"the `ticket.url` deep link","send":{"to":"servicenow"}},
  {"part":"servicenow","plain":"The incident opens in ServiceNow","tech":"`nav_to.do?uri=incident.do?sysparm_query=number=INC0012345`; the service never writes to ServiceNow"},
  {"part":"ui","start":True,"plain":"Sam's retry of the same publish does not create a second notice; a different incident needs its own number","tech":"same `externalRef` → same notice; a second notice with INC0012345 → 409 \"permanent idempotency key\"","send":{"to":"api"}},
  {"part":"api","plain":"Explains which notice already holds the number and which follow-up number is still free","tech":"409 body names the holder id; `suggestedExternalRef` is the first of INC0012345-2 … -51 the tenant does not hold yet","send":{"to":"ui","kind":"answer"}},
  {"part":"ui","plain":"The form explains it in its own terms: INC0012345 is already the reference of a notice in tenant acme; references are permanent, so a follow-up needs another one, such as INC0012345-2","tech":"`explainPublishError()` recognises a 409 that names `externalRef` and suggests the service's `suggestedExternalRef` (or `nextReference()` from an older service); the service's own text stays under a details toggle; no \"retire first\" advice"},
 ]})

JOURNEYS.append({"id":"onboard","title":"A team attaches the sidecar to its app",
 "plain":"Priya's team wants their app watched. They add one line to their deployment and a small config with the service's address and their tenant. The first report registers the app; if nothing shows up, the sidecar's own status page says why.",
 "tech":"Kustomize component (classic or native-sidecar strategic merge), Helm library chart include, or the plain YAML block; `CS_ENDPOINT` + `CS_TENANT` in a ConfigMap; image under the organisation's registry; `GET :9465/status` and `oc logs -c health-sidecar` for debugging; monitors visible at `GET /v1/health/monitors?tenantId=`.",
 "parts":parts("team","platform","sidecar","health","operator"),
 "steps":[
  {"part":"team","start":True,"plain":"Priya asks the service owners for her tenant id","tech":"tenants are assigned by the communication-service owners (a notice under an unknown tenant reaches nobody)","send":{"to":"operator"}},
  {"part":"operator","plain":"Alex gives the tenant and the service's address","tech":"`CS_TENANT=retail`, `CS_ENDPOINT=https://communication.apps.example.com`","send":{"to":"team","kind":"answer"}},
  {"part":"team","plain":"Priya adds the component to her kustomization and the config map; her Deployment itself does not change","tech":"`components: [github.com/…/sidecar/deploy/kustomize/component-native]`, ConfigMap `cs-health-sidecar`; `images:` override to the internal registry; `helm`: dependency + `include \"cs-health-sidecar.initContainer\"`","send":{"to":"platform"}},
  {"part":"platform","plain":"The next rollout starts the sidecar inside every pod of the app","tech":"native sidecar init container `restartPolicy: Always`, `securityContext` restricted-v2 (non-root, read-only, no capabilities), 16 Mi request","send":{"to":"sidecar"}},
  {"part":"sidecar","plain":"Finds the app and starts reporting","tech":"discovery; `X-Client-Id` = `CS_SERVICE` (the `app.kubernetes.io/name` label); a setting it cannot use (`CS_INTERVAL=0`, an unknown `CS_PROBE`) stops it at start with exit 2 and names the variable","send":{"to":"health"}},
  {"part":"health","plain":"The app is registered under Priya's tenant at the first report","tech":"push-only monitor auto-created; `publisher: health-sidecar`; `staleAfterSeconds: 90`"},
  {"part":"team","start":True,"plain":"\"My service does not show up\": Priya reads the sidecar's status page","tech":"`oc port-forward <pod> 9465` → `GET /status`: `target`, `upSeen`, `lastReport`, `sendError`","send":{"to":"sidecar"}},
  {"part":"sidecar","plain":"Tells her what it found and whether the last report got through","tech":"`sendError` names a wrong endpoint, a CA problem (`CS_CA_FILE`) or egress; `target` empty after the grace → set `CS_PORT`/`CS_PATH`","send":{"to":"team","kind":"answer"}},
  {"part":"team","plain":"Priya confirms on the service side that reports arrive under the right tenant","tech":"`GET /v1/health/monitors?tenantId=retail` and `…/{id}/instances` list her pods","send":{"to":"health"}},
  {"part":"health","plain":"Monitor, streaks and every pod that reported; while no pod has been UP yet the status says why in the pod's own words","tech":"e.g. `UNKNOWN (1 pod starting, none reporting yet (<pod>: no health target found after …))`; the README's three usual causes, in order: `sendError` set, wrong tenant, `upSeen` false","send":{"to":"team","kind":"answer"}},
  {"part":"team","plain":"Her pods are there under the right tenant; from now on outages publish themselves","tech":"done: no code change in the app, no RBAC, no secrets"},
 ]})

JOURNEYS.append({"id":"identity","title":"A new system calls the API for the first time",
 "plain":"A new integration tries the API, is told it must say who it is, adds its name and gets in. The same name appears in the service's access log, so Alex can see who publishes and who reads.",
 "tech":"`ClientIdWebFilter` on `/v1/**`: missing `X-Client-Id` → 401 `{\"error\": …}`, a malformed one → 400; `?clientId=` is read when there is no header, for EventSource, which cannot set headers; Swagger UI's Authorize button fills the header; INFO access log `client=<id> POST /v1/… -> 201 (32 ms)`.",
 "parts":parts("system","api","operator"),
 "steps":[
  {"part":"system","start":True,"plain":"The new integration calls the feed with no name","tech":"`GET /v1/feed?tenantId=acme` without `X-Client-Id`","send":{"to":"api"}},
  {"part":"api","plain":"Refuses politely and says what is missing","tech":"401 `{\"error\":\"missing X-Client-Id header: identify the calling system by its repository name (EventSource clients may send ?clientId= instead)\"}`; the OpenAPI document declares the `X-Client-Id` apiKey scheme","send":{"to":"system","kind":"answer"}},
  {"part":"system","plain":"Adds its repository name and calls again","tech":"`X-Client-Id: billing-portal`","send":{"to":"api"}},
  {"part":"api","plain":"Serves the feed and writes a line in the access log","tech":"200; `client=billing-portal GET /v1/feed -> 200 (9 ms)`","send":{"to":"system","kind":"answer"}},
  {"part":"system","plain":"For the live line it puts the name in the address instead","tech":"`GET /v1/feed/stream?tenantId=acme&clientId=billing-portal`","send":{"to":"api"}},
  {"part":"api","plain":"Same treatment","tech":"the same filter reads `?clientId=` when there is no header","send":{"to":"system","kind":"answer"}},
  {"part":"system","plain":"The integration is in, under its own name","tech":"every later request and stream carries `billing-portal`"},
  {"part":"operator","start":True,"plain":"Alex opens the API explorer, presses Authorize, and tries the calls by hand","tech":"Swagger UI `/swagger-ui.html` → Authorize → `X-Client-Id`; `/v3/api-docs` lists every route with its 400/401/404/409/503 bodies","send":{"to":"api"}},
  {"part":"api","plain":"Answers the explorer exactly like any client","tech":"same filter, same log line `client=alex-browser`","send":{"to":"operator","kind":"answer"}},
  {"part":"operator","plain":"Alex sees the same answers the integration got, and its name in the log","tech":"access log `client=billing-portal …` next to `client=alex-browser …`"},
 ]})

JOURNEYS.append({"id":"admin","title":"Alex tidies up across tenants",
 "plain":"Alex checks which tenants exist and how much each has published, finds a test notice someone left live, resolves it on their behalf, and removes an old one for good.",
 "tech":"`GET /v1/admin/tenants` (`TenantSummary` with counts per status), `GET /v1/admin/communications?publisher=&status=&type=&tenantId=&from=&to=` search across tenants, `POST /v1/admin/communications/{id}/retire` on anyone's notice, `DELETE /v1/admin/communications/{id}` (hard delete, history included; no stream frame is sent, so it is for notices already off the screens).",
 "parts":parts("operator","api","db","consumer"),
 "steps":[
  {"part":"operator","start":True,"plain":"Alex lists the tenants","tech":"`GET /v1/admin/tenants`","send":{"to":"api"}},
  {"part":"api","plain":"Counts notices per tenant and status","tech":"aggregation over `communications`","send":{"to":"db"}},
  {"part":"db","plain":"The counts","tech":"`TenantSummary{tenantId, counts{ACTIVE, SCHEDULED, RETIRED, …}, total}`","send":{"to":"api","kind":"answer"}},
  {"part":"api","plain":"The list","tech":"200 JSON","send":{"to":"operator","kind":"answer"}},
  {"part":"operator","plain":"Searches every tenant for live notices from the demo publisher and finds one","tech":"`GET /v1/admin/communications?publisher=demo-bot&status=ACTIVE`","send":{"to":"api"}},
  {"part":"api","plain":"Resolves it on the publisher's behalf, recording Alex as the actor","tech":"`POST /v1/admin/communications/{id}/retire {actor: alex, note}` → RETIRED + `retired` frame","send":{"to":"consumer","kind":"event"}},
  {"part":"consumer","plain":"The demo notice leaves every screen","tech":"`retired` frame"},
  {"part":"operator","start":True,"plain":"Deletes an old, long-retired notice that should never have existed","tech":"`DELETE /v1/admin/communications/{id}` → 204","send":{"to":"api"}},
  {"part":"api","plain":"Removes it for good, history included","tech":"document deleted; no event is written (it is on nobody's screen); its `externalRef` becomes free","send":{"to":"db"}},
  {"part":"db","plain":"Gone","tech":"no document; older events about it leave the log within 24 h","send":{"to":"api","kind":"answer"}},
  {"part":"api","plain":"Confirms","tech":"204 No Content","send":{"to":"operator","kind":"answer"}},
  {"part":"operator","plain":"A search no longer finds it","tech":"`GET /v1/admin/communications?publisher=…` no longer lists it; the permalink answers 404"},
 ]})

META = {
 "title": "Outage Journeys",
 "description": "Every journey through the communication service (people, dependent systems, the health sidecar) as sticky swim lanes, in plain words and in technical terms.",
 "h1": "Communication service journeys",
 "lede": "Each diagram follows one thing a person or a system does, through only the parts it touches. Time runs down the page. Every sticky is one part of the system, and every slip inside it is one step. Switch the wording to Technical for endpoints, class names and settings.",
 "rules": [
  "Arrows are numbered in order: 1, 2, 3.",
  "A step carries the number of the arrow that set it off. Arrow 4 lands on step 4a, the sticky carries on with 4b, and 4b sends arrow 5.",
  "A thin grey dashed arrow is an answer coming back. The step it lands on keeps the same number, for example 5a answers and 5b carries on.",
  "A blue arrow is news reaching everyone who listens (the live stream), not a request to one part.",
  "A step marked ▶ is where a person, a system or the clock starts something.",
 ],
 "boards": "",
}
